# exact decimal string of  m * 2^e  (e may be negative), m positive integer
sub exact {
  my ($m,$e)=@_;
  my $M=Math::BigInt->new("$m");
  if ($e>=0){ return ($M * Math::BigInt->new(2)->bpow($e))->bstr(); }
